*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:'DM Sans',sans-serif;min-height:100vh}.app-shell{max-width:1390px;margin:0 auto;padding:0 40px}.topbar{height:82px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #dfe3e9}.brand{display:flex;align-items:center;gap:12px;color:inherit;text-decoration:none}.brand-mark{width:39px;height:39px;background:var(--yellow);border:2px solid var(--ink);border-radius:11px 11px 11px 4px;display:grid;place-items:center;font-family:'Press Start 2P';font-size:17px;box-shadow:3px 3px 0 var(--ink);transform:rotate(-4deg)}.brand b{font-size:13px;letter-spacing:1.55px;display:block}.brand small{font:9px 'DM Mono',monospace;letter-spacing:1px;color:#818a9b;display:block;margin-top:5px}.top-status{font:10px 'DM Mono',monospace;letter-spacing:.7px;color:#637087;display:flex;align-items:center;gap:9px}.top-status i,.page-footer i{font-style:normal;color:#bbc1cc}.live-dot{height:7px;width:7px;border-radius:50%;background:#76a984;box-shadow:0 0 0 3px #e3f0e5}.save-button{background:white;border:1px solid #dbe0e7;border-radius:5px;padding:9px 12px;color:#526078;font:10px 'DM Mono',monospace;letter-spacing:.7px;cursor:pointer}.save-button kbd,.key-list kbd{font:10px 'DM Mono',monospace;border:1px solid #d5dbe4;border-radius:3px;padding:2px 4px;color:#657287;margin-left:5px}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 316px;gap:32px;padding:28px 0 16px}.screen-frame{background:#fff;border:1px solid #e0e4ea;border-radius:8px;box-shadow:0 8px 26px #15233a0c;padding:14px}.screen-label,.screen-bottom{height:23px;display:flex;justify-content:space-between;align-items:center;padding:0 4px;color:#718096;font:9px 'DM Mono',monospace;letter-spacing:1px}.screen-label span:first-child{color:#314158;font-weight:500}.screen-bottom{height:25px;padding-top:5px}.screen-bottom b{color:#76a984;font-size:12px;vertical-align:-1px}.canvas-wrap{position:relative;width:min(100%,720px);margin:0 auto;background:#93c7ad;overflow:hidden;aspect-ratio:4/3;image-rendering:pixelated}.canvas-wrap canvas{display:block;width:100%;height:100%;image-rendering:pixelated}.toast{position:absolute;left:50%;bottom:10px;transform:translate(-50%,10px);background:#17243ae8;color:white;border:1px solid #fff4;padding:8px 13px;border-radius:4px;white-space:nowrap;font:10px 'DM Mono',monospace;opacity:0;transition:.18s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.controls-row{min-height:112px;background:#fff;border:1px solid #e0e4ea;border-radius:8px;margin-top:13px;display:flex;align-items:center;padding:14px 21px;gap:24px}.dpad{width:66px;height:66px;display:grid;grid-template:repeat(3,22px)/repeat(3,22px);position:relative;flex:none}.dpad button{border:0;background:#e8ebf0;color:#6b7687;font-size:11px;padding:0;cursor:pointer;box-shadow:0 2px 0 #cbd1da}.dpad .up{grid-area:1/2;border-radius:4px 4px 0 0}.dpad .left{grid-area:2/1;border-radius:4px 0 0 4px}.dpad .down{grid-area:3/2;border-radius:0 0 4px 4px}.dpad .right{grid-area:2/3;border-radius:0 4px 4px 0}.dpad-center{grid-area:2/2;background:#e8ebf0;box-shadow:0 2px 0 #cbd1da}.control-hint{flex:1;min-width:0}.control-hint>b{font-size:10px;letter-spacing:1px}.control-hint>span{display:block;color:#828c9d;font-size:11px;line-height:1.55;margin-top:4px;max-width:380px}.key-list{margin-top:7px;color:#8791a1;font:9px 'DM Mono',monospace;display:flex;align-items:center;gap:3px}.key-list kbd{margin:0 1px}.action-keys{display:flex;gap:8px}.round-key{height:45px;width:45px;border:0;border-radius:50%;background:#d85e64;color:#fff;box-shadow:0 3px 0 #b44b54;display:flex;flex-direction:column;justify-content:center;align-items:center;cursor:pointer}.round-key b{font:bold 17px 'DM Sans'}.round-key small{font:7px 'DM Mono',monospace;opacity:.85;margin-top:1px}.round-key.secondary{background:#7993ae;box-shadow:0 3px 0 #5c738e}.sidebar{display:flex;flex-direction:column;gap:12px}.trainer-card,.party-card,.map-card,.journal-card{background:white;border:1px solid #e1e5eb;border-radius:7px;padding:14px 15px}.card-kicker{font:9px 'DM Mono',monospace;letter-spacing:.7px;color:#828c9e;display:flex;justify-content:space-between}.card-kicker span{color:#b1b8c5}.trainer-row{display:flex;align-items:center;gap:11px;margin:12px 0 14px}.trainer-avatar{height:41px;width:41px;border-radius:50%;background:#f8eab9;display:grid;place-items:center;color:#aa8151;font-size:27px;border:2px solid #f3de9b;box-shadow:inset 0 -7px #edcf79}.trainer-row h1{font-size:13px;letter-spacing:1.3px;margin:0}.trainer-row p{font:8px 'DM Mono',monospace;color:#9099a8;margin:4px 0 0;letter-spacing:.3px}.icon-button{margin-left:auto;border:0;background:transparent;color:#9da6b4;cursor:pointer;font-size:16px}.trainer-stats{border-top:1px solid #edf0f3;padding-top:10px;display:grid;grid-template-columns:repeat(3,1fr)}.trainer-stats>div{border-right:1px solid #edf0f3;padding-left:9px}.trainer-stats>div:first-child{padding-left:0}.trainer-stats>div:last-child{border:0}.trainer-stats small,.item-strip small{font:8px 'DM Mono',monospace;color:#9aa3b0;display:block;letter-spacing:.4px}.trainer-stats b{font:12px 'DM Mono',monospace;display:block;margin-top:5px}.trainer-stats i{font-style:normal;font-size:9px;color:#aab1bc}.section-heading{height:17px;display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}.section-heading h2{font-size:9px;letter-spacing:1px;margin:0}.section-heading>span{font:9px 'DM Mono',monospace;color:#a0a9b7}.party-card{padding-bottom:10px}.party-list{display:flex;flex-direction:column;gap:5px}.party-row{display:grid;grid-template-columns:26px 1fr auto;align-items:center;gap:8px;padding:5px 6px;border-radius:4px;background:#f8f9fb}.mon-avatar{height:25px;width:25px;border-radius:7px;background:#fff0c8;display:grid;place-items:center;font-size:16px}.mon-name{font-weight:700;font-size:10px;letter-spacing:.2px}.mon-sub{color:#99a2b0;font:8px 'DM Mono',monospace;margin-top:2px}.hp-mini{width:66px;height:4px;border-radius:4px;background:#e8ebee;overflow:hidden}.hp-mini i{height:100%;display:block;background:#7cac72}.hp-mini.low i{background:#e2a249}.party-hp{font:8px 'DM Mono',monospace;color:#8590a0;text-align:right;margin-top:3px}.item-strip{border-top:1px solid #edf0f3;margin-top:9px;padding-top:10px;display:flex;align-items:center;gap:8px}.pokeball-icon{border:2px solid #db6264;height:17px;width:17px;border-radius:50%;display:grid;place-items:center;color:#db6264;font-size:8px;background:linear-gradient(#e86769 45%,#48536a 46%,#48536a 55%,#fff 56%)}.item-strip b{font:8px 'DM Mono',monospace;display:block;margin-top:3px;letter-spacing:.2px}.item-strip b i{font-style:normal;color:#afb6c0}.text-button{border:0;background:transparent;font:8px 'DM Mono',monospace;color:#8290a4;letter-spacing:.4px;cursor:pointer}.item-strip .text-button{margin-left:auto}.map-card{padding-bottom:11px}.section-heading .text-button{padding:0}.mini-map{height:86px;background:#f4f6f2;border-radius:4px;position:relative;overflow:hidden;display:grid;grid-template-columns:repeat(22,1fr);grid-template-rows:repeat(10,1fr);gap:1px;padding:5px}.map-cell{background:#e4e9e2;border-radius:1px;opacity:.55}.map-cell.discovered{background:#aac6a7;opacity:1}.map-cell.current{background:#e8bd4c;opacity:1;box-shadow:0 0 0 1px #fff inset}.map-legend{display:flex;align-items:center;gap:9px;margin-top:8px;font:7px 'DM Mono',monospace;color:#929baa}.map-legend span{display:flex;align-items:center;gap:3px}.map-legend span:last-child{margin-left:auto;color:#66738a}.map-legend i{width:6px;height:6px;border-radius:1px;background:#e8bd4c}.map-legend .legend-known{background:#aac6a7}.journal-card{min-height:80px}.note-dot{color:#e4bd4c!important}.journal-entry{display:flex;align-items:flex-start;gap:7px;color:#788496;font-size:9px;line-height:1.5;margin:6px 0 0}.journal-entry i{font-style:normal;color:#c7a33f;font-size:11px}.side-footer{margin-top:auto;display:flex;justify-content:space-between;padding:5px 2px;color:#a1aab8;font:8px 'DM Mono',monospace;letter-spacing:.4px}.page-footer{height:37px;border-top:1px solid #e1e5eb;display:flex;justify-content:space-between;align-items:center;color:#929baa;font:8px 'DM Mono',monospace;letter-spacing:.65px}.page-footer span:first-child{color:#6e7c91}
/* in-game overlays */.battle-panel,.map-panel,.menu-panel{position:absolute;inset:0;background:#152039eF;color:#fff;padding:15px;z-index:3;overflow:auto}.battle-panel.hidden,.map-panel.hidden,.menu-panel.hidden{display:none}.battle-top{display:flex;justify-content:space-between;align-items:center;font:9px 'DM Mono',monospace;color:#dce1e8;letter-spacing:.7px}.battle-stage{height:116px;position:relative;margin:8px 0;background:linear-gradient(#9ec7b3 0 62%,#83b08c 62%);border:2px solid #243b49;border-radius:3px;overflow:hidden}.battle-stage:before,.battle-stage:after{content:'';position:absolute;border-radius:50%;background:#c9db8a;opacity:.5;width:150px;height:35px}.battle-stage:before{left:-17px;bottom:2px}.battle-stage:after{right:-20px;top:24px}.enemy-sprite,.ally-sprite{position:absolute;z-index:1;font-size:54px;filter:drop-shadow(0 3px 1px #425a4a66)}.enemy-sprite{right:47px;top:6px}.ally-sprite{left:50px;bottom:1px;font-size:48px}.battle-info{background:#fff;color:#1b2b42;padding:7px 9px;border-radius:4px;width:133px;position:absolute;z-index:2;box-shadow:2px 2px #1f3443}.battle-info.player{right:5px;bottom:4px}.battle-info.foe{left:5px;top:4px}.battle-info b{font-size:9px}.battle-info .level{float:right;color:#7a8798;font:8px 'DM Mono',monospace}.battle-info small{display:block;font:7px 'DM Mono',monospace;color:#6f7a8a;margin-top:4px}.battle-hp{height:4px;background:#e8e9df;border-radius:3px;margin-top:5px;overflow:hidden}.battle-hp i{display:block;height:100%;background:#7bac71}.battle-copy{font:9px 'DM Mono',monospace;line-height:1.6;color:#e8ebf0;min-height:26px;margin:7px 1px}.battle-actions{display:grid;grid-template-columns:1fr 1fr;gap:6px}.battle-actions button,.overlay-button{border:1px solid #ffffff3d;background:#23314c;color:#fff;padding:8px 9px;text-align:left;border-radius:3px;font:9px 'DM Mono',monospace;cursor:pointer}.battle-actions button:hover,.overlay-button:hover{background:#394968}.battle-actions button span{float:right;color:#aeb9ca}.map-panel,.menu-panel{background:#f7f5eb;color:#17243a;padding:14px}.overlay-head{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #d7d9d2;padding-bottom:9px;margin-bottom:10px}.overlay-head b{font:10px 'DM Mono',monospace;letter-spacing:1px}.close-x{border:0;background:none;color:#718095;font-size:17px;cursor:pointer}.atlas-grid{display:grid;grid-template-columns:repeat(22,1fr);grid-template-rows:repeat(10,1fr);gap:2px;height:146px}.atlas-cell{background:#e0e6dc;border-radius:1px;position:relative}.atlas-cell.discovered{background:#a5c5a5}.atlas-cell.current{background:#e6bd4b;box-shadow:0 0 0 2px white inset}.atlas-caption{font:8px 'DM Mono',monospace;color:#66738a;line-height:1.6;margin:9px 0}.map-zones{display:grid;grid-template-columns:1fr 1fr;gap:5px;max-height:92px;overflow:auto}.map-zone{border:1px solid #e1e3dc;background:#fff;border-radius:3px;padding:5px;font:8px 'DM Mono',monospace;color:#647188;text-align:left;cursor:pointer}.map-zone.visited{color:#355e48}.map-zone b{color:#ba9636;margin-right:4px}.map-zone:disabled{opacity:.55;cursor:default}.menu-items{display:grid;grid-template-columns:1fr 1fr;gap:8px}.menu-item{border:1px solid #e0e3db;background:#fff;padding:11px;border-radius:4px;text-align:left;cursor:pointer;color:#34435a}.menu-item b{display:block;font-size:10px;margin-bottom:4px}.menu-item small{font:8px 'DM Mono',monospace;color:#8791a0}.notice{font:9px 'DM Mono',monospace;color:#718095;margin-top:12px}.capture-flash{animation:flash .2s}@keyframes flash{50%{filter:brightness(1.7)}}
@media(max-width:980px){.app-shell{padding:0 20px}.game-layout{grid-template-columns:minmax(0,1fr) 280px;gap:16px}.controls-row{gap:14px;padding:12px}.canvas-wrap{width:100%}.map-legend{gap:5px;font-size:6px}}
@media(max-width:740px){.app-shell{padding:0 12px}.topbar{height:66px}.top-status{display:none}.game-layout{display:flex;flex-direction:column;padding-top:15px;gap:14px}.sidebar{display:grid;grid-template-columns:1fr 1fr;align-items:start}.trainer-card,.party-card,.map-card,.journal-card{grid-column:auto}.journal-card{min-height:100%}.side-footer{grid-column:span 2}.screen-frame{padding:9px}.controls-row{min-height:96px}.control-hint>span{font-size:10px}.key-list{font-size:7px;flex-wrap:wrap}.action-keys{gap:5px}.round-key{width:39px;height:39px}.page-footer{font-size:7px}.page-footer span:first-child{display:none}.page-footer{justify-content:center}}
@media(max-width:440px){.sidebar{grid-template-columns:1fr}.side-footer{grid-column:auto}.controls-row{padding:10px;gap:10px}.dpad{transform:scale(.85);transform-origin:left center;width:56px}.action-keys{flex-direction:column}.control-hint>span{font-size:9px}.key-list{display:none}.screen-label,.screen-bottom{font-size:7px}.canvas-wrap{aspect-ratio:4/3}.brand b{font-size:11px}.brand small{font-size:8px}}

(() => {
  'use strict';
  const W=320,H=240,T=16,COLS=20,ROWS=15, $=s=>document.querySelector(s);
  const canvas=$('#game'),ctx=canvas.getContext('2d'); ctx.imageSmoothingEnabled=false;
  const names=['Pallet Town','Route 1','Viridian City','Viridian Forest','Pewter City','Route 3','Mt. Moon','Route 4','Cerulean City','Route 5','Vermilion City','Rock Tunnel','Lavender Town','Celadon City','Saffron City','Fuchsia City','Safari Zone','Cinnabar Island','Seafoam Islands','Victory Road','Indigo Plateau'];
  const townMap={'0,0':['Pallet Town','Coastal village'],'2,0':['Viridian City','Forest gateway'],'4,0':['Pewter City','Stone city'],'8,1':['Cerulean City','Riverside city'],'10,3':['Vermilion City','Harbor town'],'12,3':['Lavender Town','Quiet town'],'13,2':['Celadon City','Garden city'],'14,3':['Saffron City','Crossroads city'],'16,5':['Fuchsia City','Safari town'],'18,8':['Cinnabar Island','Volcanic island'],'20,9':['Indigo Plateau','League summit'],'1,1':['Viridian Forest','Deep woodland'],'6,1':['Mt. Moon','Cavern pass'],'11,6':['Rock Tunnel','Mountain tunnel'],'17,6':['Seafoam Islands','Tidal caves'],'19,8':['Victory Road','Final passage'],'16,4':['Safari Zone','Wildlife preserve']};
  const monData={Pikachu:['⚡',35,55,90,'Electric','#f2ca4c'],Pidgey:['◉',40,45,56,'Flying','#bd9871'],Rattata:['◉',30,56,72,'Normal','#9b76a0'],Caterpie:['●',45,30,45,'Bug','#78ad67'],Weedle:['●',40,35,50,'Bug','#c6a36c'],Nidoran:['◆',46,57,50,'Poison','#7796b9'],Oddish:['✿',45,50,30,'Grass','#588c58'],Meowth:['◉',40,45,90,'Normal','#e8d08b'],Zubat:['◒',40,45,55,'Poison','#8192b6'],Geodude:['◆',40,80,20,'Rock','#9a8b7b'],Psyduck:['●',50,52,55,'Water','#e5c95b'],Magikarp:['◒',20,10,80,'Water','#db8361']};
  const encByType={field:['Pidgey','Rattata','Caterpie','Weedle','Pikachu','Oddish'],forest:['Caterpie','Weedle','Pikachu','Pidgey','Oddish'],cave:['Zubat','Geodude','Rattata'],water:['Psyduck','Magikarp','Pidgey'],town:['Pidgey','Rattata','Meowth']};
  const state={x:10,y:11,px:0,py:0,dir:'up',steps:0,money:300,balls:5,potions:3,badges:0,party:[],seen:new Set(['0,0']),zoneKey:'0,0',mode:'field',battle:null,trainer:'RED',journal:[],tick:0,encounterLock:0};
  const key=(x=state.px,y=state.py)=>`${x},${y}`,zoneId=(x,y)=>y*22+x+1;
  function zoneInfo(x=state.px,y=state.py){const custom=townMap[`${x},${y}`];if(custom)return {name:custom[0],type:custom[1],kind:/city|town|village|summit|island$/.test(custom[1])?'town':/forest|woodland/.test(custom[1])?'forest':/cave|tunnel|pass/.test(custom[1])?'cave':/island|tidal/.test(custom[1])?'water':'field'};let id=zoneId(x,y), route=Math.abs(x-y)%24+1;return {name:`Route ${route}`,type:['Open grassland','Woodland trail','Riverside path','Mountain foothills'][((x*3+y*7)%4)],kind:(x*3+y*7)%7===0?'forest':(x*3+y*7)%11===0?'cave':'field',id};}
  function hash(x,y,n=0){let a=(x+17)*374761393+(y+31)*668265263+(n+7)*1442695041;a=(a^(a>>>13))*1274126177;return (a^(a>>>16))>>>0}
  function rand(a){state.tick=(state.tick*1664525+1013904223)>>>0;return a?state.tick%a:0}
  function isPath(x,y){return y===7||y===8||x===9||x===10}
  function tile(x,y){if(x<0||y<0||x>=COLS||y>=ROWS)return 0;let z=zoneInfo(),h=hash(state.px,state.py,x*ROWS+y),path=isPath(x,y),kind=z.kind;if(path)return 1;if(kind==='water'&&(y<3||x<3&&y<6))return h%4===0?0:4;if(kind==='cave')return h%8===0?0:h%9===0?5:6;if(kind==='forest')return h%7<3?2:h%15===0?5:0;if(z.kind==='town'){if((x<3||x>16||y<2||y>12)&&h%3!==0)return 2;return h%28===0?3:0}if(h%11<3)return 2;if(h%47===0)return 5;if(h%38===0)return 3;return 0}
  function walkable(x,y){let v=tile(x,y);return v===0||v===1||v===4}
  function visit(){state.zoneKey=key();state.seen.add(state.zoneKey);let z=zoneInfo();$('#areaLabel').textContent=z.name.toUpperCase();$('#segmentLabel').textContent=`ZONE ${String(zoneId(state.px,state.py)).padStart(3,'0')} / 220`;$('#zoneType').textContent=z.type.toUpperCase();$('#clockText').textContent=`DAY ${String(1+Math.floor(state.steps/180)).padStart(2,'0')} · ${String(8+Math.floor(state.steps/30)%12).padStart(2,'0')}:00`;updateUI();draw();}
  function transition(dx,dy){let nx=state.px+dx,ny=state.py+dy;if(nx<0||nx>=22||ny<0||ny>=10){toast('The Kanto region ends here.');return false}state.px=nx;state.py=ny;state.x=dx===1?0:dx===-1?COLS-1:10;state.y=dy===1?0:dy===-1?ROWS-1:state.y;addNote(`Discovered ${zoneInfo().name} · Zone ${String(zoneId(nx,ny)).padStart(3,'0')}`);visit();toast(zoneInfo().name);return true}
  function tileDraw(x,y){let v=tile(x,y),px=x*T,py=y*T,h=hash(state.px,state.py,x*ROWS+y);if(v===0){ctx.fillStyle=(h%5===0?'#9bc7a2':'#91c29b');ctx.fillRect(px,py,T,T);if(h%4===0){ctx.fillStyle='#b4d2a7';ctx.fillRect(px+3,py+4,2,2);ctx.fillRect(px+10,py+11,2,2)}if(h%9===0){ctx.fillStyle='#789e79';ctx.fillRect(px+7,py+3,2,4);ctx.fillRect(px+5,py+6,6,2)}}else if(v===1){ctx.fillStyle='#d9c595';ctx.fillRect(px,py,T,T);ctx.fillStyle='#e6d5aa';ctx.fillRect(px,py+1,T,2);ctx.fillStyle='#cbb583';if(h%3===0)ctx.fillRect(px+4,py+9,2,2);if(h%5===0)ctx.fillRect(px+11,py+5,2,2)}else if(v===2){ctx.fillStyle='#8cba8e';ctx.fillRect(px,py,T,T);ctx.fillStyle='#d5df8b';ctx.fillRect(px+3,py+3,2,6);ctx.fillRect(px+6,py+6,2,7);ctx.fillRect(px+10,py+2,2,8);ctx.fillRect(px+13,py+7,2,6);ctx.fillStyle='#659c73';ctx.fillRect(px+1,py+10,2,4)}else if(v===3){ctx.fillStyle='#90bd96';ctx.fillRect(px,py,T,T);ctx.fillStyle='#f7e5a1';ctx.fillRect(px+4,py+8,3,3);ctx.fillStyle='#fff4c2';ctx.fillRect(px+5,py+7,1,1)}else if(v===4){ctx.fillStyle='#75adbb';ctx.fillRect(px,py,T,T);ctx.fillStyle='#a1cfca';ctx.fillRect(px+2,py+4+(h%5),6,1);ctx.fillRect(px+10,py+11,4,1)}else if(v===5){ctx.fillStyle='#77966c';ctx.fillRect(px,py,T,T);ctx.fillStyle='#43684e';ctx.fillRect(px+2,py+7,12,8);ctx.fillStyle='#58805b';ctx.fillRect(px+4,py+3,8,8);ctx.fillStyle='#71996d';ctx.fillRect(px+6,py+1,5,6);ctx.fillStyle='#886d4d';ctx.fillRect(px+7,py+12,3,4)}else if(v===6){ctx.fillStyle='#958776';ctx.fillRect(px,py,T,T);ctx.fillStyle='#a99c87';if(h%2)ctx.fillRect(px+2,py+3,5,2);ctx.fillStyle='#71695f';ctx.fillRect(px+12,py+9,3,4)}}
  function drawPerson(x,y,kind='player',dir=state.dir){let px=x*T,py=y*T;if(kind==='pikachu'){ctx.fillStyle='#d7ad35';ctx.fillRect(px+4,py+5,9,8);ctx.fillRect(px+3,py+7,11,5);ctx.fillStyle='#f4d14e';ctx.fillRect(px+5,py+4,7,8);ctx.fillRect(px+2,py+2,3,6);ctx.fillRect(px+12,py+2,3,6);ctx.fillStyle='#bd5147';ctx.fillRect(px+3,py+6,2,2);ctx.fillRect(px+12,py+6,2,2);ctx.fillStyle='#493d32';ctx.fillRect(px+7,py+7,1,1);ctx.fillRect(px+11,py+7,1,1);ctx.fillStyle='#e7ae4b';ctx.fillRect(px+6,py+12,2,2);ctx.fillRect(px+11,py+12,2,2);ctx.fillStyle='#d88937';ctx.fillRect(px+1,py+7,2,2);ctx.fillRect(px+14,py+7,2,2);return}
    if(kind==='npc'){ctx.fillStyle='#774f50';ctx.fillRect(px+4,py+1,8,4);ctx.fillStyle='#d6a17f';ctx.fillRect(px+5,py+4,7,6);ctx.fillStyle='#527b74';ctx.fillRect(px+3,py+9,11,5);ctx.fillStyle='#31475b';ctx.fillRect(px+4,py+14,3,2);ctx.fillRect(px+10,py+14,3,2);return}
    // Player: red cap, warm jacket, tiny backpack
    ctx.fillStyle='#373c54';ctx.fillRect(px+5,py+14,3,2);ctx.fillRect(px+10,py+14,3,2);ctx.fillStyle='#e4af87';ctx.fillRect(px+5,py+5,7,7);ctx.fillStyle='#c64f54';ctx.fillRect(px+3,py+2,10,4);ctx.fillRect(px+5,py+1,7,2);ctx.fillStyle='#f2d36e';ctx.fillRect(px+7,py+7,1,1);ctx.fillRect(px+10,py+7,1,1);ctx.fillStyle='#456b88';ctx.fillRect(px+4,py+11,9,4);ctx.fillStyle='#a6454d';ctx.fillRect(px+2,py+11,3,4);if(dir==='left')ctx.fillRect(px+3,py+8,2,3);else if(dir==='right')ctx.fillRect(px+12,py+8,2,3);
  }
  function draw(){ctx.clearRect(0,0,W,H);let z=zoneInfo();for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++)tileDraw(x,y);
    // decorative town roofs / signs
    if(z.kind==='town'){for(const [x,y,c] of [[2,2,'#d58468'],[15,2,'#758ca4'],[2,11,'#d1a26a'],[15,11,'#9b7898']]){ctx.fillStyle='#596c70';ctx.fillRect(x*T,y*T+7,30,22);ctx.fillStyle=c;ctx.fillRect(x*T-2,y*T+3,34,11);ctx.fillStyle='#f3e4bf';ctx.fillRect(x*T+6,y*T+12,6,7);ctx.fillRect(x*T+19,y*T+12,6,7);}}
    // signs and friendly people
    let n=hash(state.px,state.py,991)%4;let npcX=[5,14,5,15][n],npcY=[6,5,10,9][n];if(z.kind==='town'||state.px===1&&state.py===0){drawPerson(npcX,npcY,'npc');ctx.fillStyle='#f4f1de';ctx.fillRect(npcX*T+4,npcY*T-4,9,4);ctx.fillStyle='#566876';ctx.font='5px monospace';ctx.fillText('!',npcX*T+7,npcY*T-1)}
    // player companion trails by a tile
    let bx=state.x,by=state.y;if(state.dir==='up')by=Math.min(14,by+1);if(state.dir==='down')by=Math.max(0,by-1);if(state.dir==='left')bx=Math.min(19,bx+1);if(state.dir==='right')bx=Math.max(0,bx-1);drawPerson(bx,by,'pikachu');drawPerson(state.x,state.y,'player');
    // tiny scene title
    ctx.fillStyle='#263a42';ctx.fillRect(5,5,Math.min(130,z.name.length*5+12),14);ctx.fillStyle='#fff';ctx.font='7px monospace';ctx.fillText(z.name.toUpperCase(),10,14);
  }
  function addNote(text){state.journal.unshift(text);state.journal=state.journal.slice(0,4);updateUI()}
  let toastTimer;function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1700)}
  function updateUI(){const z=zoneInfo();$('#stepCount').textContent=String(state.steps).padStart(4,'0');$('#trainerName').textContent=state.trainer.toUpperCase();$('#badgeCount').innerHTML=`${String(state.badges).padStart(2,'0')} <i>/ 08</i>`;$('#ballCount').textContent=String(state.balls).padStart(2,'0');$('#potionCount').textContent=String(state.potions).padStart(2,'0');$('#partyCount').textContent=`${String(state.party.length).padStart(2,'0')} / 06`;$('#discoveryText').textContent=`${state.seen.size} / 220 ZONES`;$('#dexCount').innerHTML=`${String(1+state.seenMons.size).padStart(3,'0')} <i>/ 151</i>`;
    $('#partyList').innerHTML=state.party.map((m,i)=>{let d=monData[m.name];return `<div class="party-row"><div class="mon-avatar" style="background:${d[5]}30;color:${d[5]}">${d[0]}</div><div><div class="mon-name">${m.name}</div><div class="mon-sub">LV. ${m.lv} · ${d[4].toUpperCase()}</div></div><div><div class="hp-mini ${m.hp<m.max*.3?'low':''}"><i style="width:${100*m.hp/m.max}%"></i></div><div class="party-hp">${m.hp}/${m.max} HP</div></div></div>`}).join('');
    $('#journal').innerHTML=state.journal.slice(0,3).map(x=>`<div class="journal-entry"><i>✦</i><span>${x}</span></div>`).join('')||'<div class="journal-entry">Your journey starts here.</div>';
    const mini=$('#miniMap');mini.innerHTML='';for(let y=0;y<10;y++)for(let x=0;x<22;x++){let k=`${x},${y}`,el=document.createElement('i');el.className='map-cell'+(state.seen.has(k)?' discovered':'')+(state.px===x&&state.py===y?' current':'');mini.appendChild(el)}
  }
  state.seenMons=new Set();
  function newMon(name,lv){let d=monData[name],max=d[1]+lv*3;return {name,lv,max,hp:max,xp:0,atk:d[2]+lv,spd:d[3]+lv}}
  function addMon(name,lv=3){if(state.party.length<6){let m=newMon(name,lv);state.party.push(m);state.seenMons.add(name);updateUI();return true}return false}
  function move(dx,dy){if(state.mode!=='field')return;state.dir=dy<0?'up':dy>0?'down':dx<0?'left':'right';let nx=state.x+dx,ny=state.y+dy;
    if(nx<0){if(state.x===0&&state.y>=7&&state.y<=8)transition(-1,0);else toast('The path is blocked.');return}if(nx>=COLS){if(state.x===COLS-1&&state.y>=7&&state.y<=8)transition(1,0);else toast('The path is blocked.');return}if(ny<0){if(state.y===0&&state.x>=9&&state.x<=10)transition(0,-1);else toast('The path is blocked.');return}if(ny>=ROWS){if(state.y===ROWS-1&&state.x>=9&&state.x<=10)transition(0,1);else toast('The path is blocked.');return}
    if(!walkable(nx,ny)||((nx===5||nx===14)&&ny===6&&zoneInfo().kind==='town')){toast('A little too dense to pass through.');return}
    state.x=nx;state.y=ny;state.steps++;if(state.encounterLock>0)state.encounterLock--;visit();if(tile(nx,ny)===2&&state.encounterLock===0&&Math.random()<.14)startBattle(false);
  }
  function encounterName(){let a=encByType[zoneInfo().kind]||encByType.field;return a[rand(a.length)]}
  function startBattle(trainer=false,forced){if(state.mode!=='field')return;let name=forced||encounterName(),lv=Math.max(2,Math.min(12,2+Math.floor(state.steps/18)+rand(3)));let foe=newMon(name,lv);state.battle={foe,trainer,turn:'player',text:trainer?`A trainer challenges you with ${name}!`:`A wild ${name} appeared!`};state.mode='battle';$('#statusText').textContent=trainer?'TRAINER BATTLE':'WILD ENCOUNTER';renderBattle();}
  function hpbar(m){return `<div class="battle-hp"><i style="width:${Math.max(0,m.hp/m.max*100)}%;background:${m.hp/m.max<.25?'#dc8060':'#7bac71'}"></i></div>`}
  function renderBattle(){if(!state.battle)return;let b=state.battle,p=state.party[0],f=b.foe;let panel=$('#battlePanel');panel.classList.remove('hidden');panel.innerHTML=`<div class="battle-top"><span>${b.trainer?'TRAINER BATTLE':'WILD POKÉMON'}</span><span>ZONE ${String(zoneId(state.px,state.py)).padStart(3,'0')}</span></div><div class="battle-stage"><div class="battle-info foe"><b>${f.name}</b><span class="level">Lv ${f.lv}</span>${hpbar(f)}<small>HP ${Math.max(0,f.hp)} / ${f.max}</small></div><div class="enemy-sprite" style="color:${monData[f.name][5]}">${monData[f.name][0]}</div><div class="ally-sprite" style="color:${monData[p.name][5]}">${monData[p.name][0]}</div><div class="battle-info player"><b>${p.name}</b><span class="level">Lv ${p.lv}</span>${hpbar(p)}<small>HP ${p.hp} / ${p.max}</small></div></div><div class="battle-copy">${b.text}</div><div class="battle-actions"><button data-battle="attack">✦  THUNDER SHOCK <span>PP 25/25</span></button><button data-battle="ball">◉  POKÉ BALL <span>${state.balls}</span></button><button data-battle="potion">✚  POTION <span>${state.potions}</span></button><button data-battle="run">↗  RUN</button></div>`;panel.querySelectorAll('[data-battle]').forEach(x=>x.onclick=()=>battleAction(x.dataset.battle));}
  function endBattle(text,win=false){if(!state.battle)return;state.battle.text=text;renderBattle();setTimeout(()=>{if(!state.battle)return;$('#battlePanel').classList.add('hidden');state.battle=null;state.mode='field';state.encounterLock=4;$('#statusText').textContent='FIELD EXPLORATION';if(win){state.steps+=1;updateUI()}draw()},1200)}
  function battleAction(action){let b=state.battle;if(!b)return;let p=state.party[0],f=b.foe;if(action==='run'){if(b.trainer){b.text='You cannot run from a trainer battle!';renderBattle();return}endBattle('You got away safely.');return}if(action==='ball'){if(b.trainer){b.text='You cannot catch another trainer’s Pokémon!';renderBattle();return}if(state.balls<=0){b.text='You are out of Poké Balls!';renderBattle();return}state.balls--;if(Math.random()<.2+(.65*(1-f.hp/f.max))){state.seenMons.add(f.name);if(addMon(f.name,f.lv)){endBattle(`Gotcha! ${f.name} joined your party!`,true);addNote(`${f.name} joined your team.`)}else endBattle(`Gotcha! ${f.name} was sent to the PC.`,true)}else{b.text=`Oh no! ${f.name} broke free!`;renderBattle();enemyTurn()}updateUI();return}if(action==='potion'){if(!state.potions){b.text='You have no Potions left.';renderBattle();return}if(p.hp>=p.max){b.text=`${p.name} is already at full health.`;renderBattle();return}state.potions--;p.hp=Math.min(p.max,p.hp+20);b.text=`Your Potion restored ${p.name}'s energy!`;renderBattle();updateUI();enemyTurn();return}
    let damage=Math.max(5,Math.floor(p.atk*.55)+rand(6));f.hp=Math.max(0,f.hp-damage);if(f.hp===0){p.xp+=12+f.lv*3;b.text=`${f.name} fainted! ${p.name} gained experience.`;if(p.xp>=p.lv*20){p.xp=0;p.lv++;p.max+=3;p.hp=Math.min(p.max,p.hp+3);p.atk+=1;b.text+=` ${p.name} grew to Lv ${p.lv}!`}if(b.trainer&&state.badges<8){state.badges++;b.text+=' You earned a Gym Badge!'}renderBattle();endBattle(b.text,true);addNote(`${p.name} won a battle${b.trainer?' and earned a badge':''}.`);updateUI();return}b.text=`${p.name} used Thunder Shock! ${damage} damage.`;renderBattle();enemyTurn();}
  function enemyTurn(){let b=state.battle;if(!b)return;let p=state.party[0],f=b.foe,dmg=Math.max(2,Math.floor(f.atk*.22)+rand(4));p.hp=Math.max(0,p.hp-dmg);if(!p.hp){p.hp=Math.ceil(p.max*.4);b.text=`${p.name} fainted! You hurried to the Pokémon Center.`;renderBattle();endBattle(b.text);addNote('Rested up at a Pokémon Center.')}else{b.text+=` ${f.name} struck back for ${dmg}!`;renderBattle()}updateUI()}
  function interact(){if(state.mode==='battle')return;if(state.mode!=='field')return;let x=state.x,y=state.y;if(x===10&&y===11&&state.px===0&&state.py===0){toast('Your home — the place every adventure begins.');return}let candidates=[[x,y-1],[x,y+1],[x-1,y],[x+1,y]];for(let [cx,cy] of candidates){if(cx===[5,14][hash(state.px,state.py,991)%4]&&cy===[6,5,10,9][hash(state.px,state.py,991)%4]&&(zoneInfo().kind==='town'||state.px===1)){let dialog=['The road ahead is full of surprises. Keep your partner close!','I heard the next town has a wonderful Pokémon Center.','Tall grass rustles nearby... You might find a new friend!','A good trainer always takes time to explore.'][rand(4)];toast(dialog);addNote(dialog);return}}
    if((x===10&&y===7)||(x===9&&y===8)){toast('A wooden sign: “Kanto is a big place. Follow the paths!”');return}toast('Pikachu gives you an encouraging little chirp!');}
  function toggleMap(){if(state.mode==='battle')return;if(state.mode==='map'){closeOverlay();return}state.mode='map';let panel=$('#mapPanel');panel.classList.remove('hidden');let cells='';for(let y=0;y<10;y++)for(let x=0;x<22;x++){let k=`${x},${y}`;cells+=`<i class="atlas-cell${state.seen.has(k)?' discovered':''}${x===state.px&&y===state.py?' current':''}" title="Zone ${zoneId(x,y)}"></i>`}let nearby=[];for(let y=Math.max(0,state.py-2);y<=Math.min(9,state.py+2);y++)for(let x=Math.max(0,state.px-2);x<=Math.min(21,state.px+2);x++){let k=`${x},${y}`;nearby.push(`<button class="map-zone${state.seen.has(k)?' visited':''}" ${state.seen.has(k)?'':'disabled'} data-go="${k}"><b>${String(zoneId(x,y)).padStart(3,'0')}</b>${zoneInfo(x,y).name}</button>`)}panel.innerHTML=`<div class="overlay-head"><b>KANTO REGIONAL ATLAS</b><button class="close-x" data-close>×</button></div><div class="atlas-grid">${cells}</div><div class="atlas-caption">220 connected field zones · Amber marks your current location. Walk along the roads to discover every corner of Kanto.</div><div class="map-zones">${nearby.join('')}</div>`;panel.querySelector('[data-close]').onclick=closeOverlay;panel.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{let [x,y]=b.dataset.go.split(',').map(Number);if(state.seen.has(key(x,y))){state.px=x;state.py=y;state.x=10;state.y=7;closeOverlay();visit()}})}
  function openMenu(tab='menu'){if(state.mode==='battle')return;state.mode='menu';let panel=$('#menuPanel');panel.classList.remove('hidden');panel.innerHTML=`<div class="overlay-head"><b>TRAINER'S MENU</b><button class="close-x" data-close>×</button></div><div class="menu-items"><button class="menu-item" data-menu="party"><b>⚡ Partner</b><small>Check your team</small></button><button class="menu-item" data-menu="bag"><b>◉ Bag</b><small>${state.balls} Poké Balls · ${state.potions} Potions</small></button><button class="menu-item" data-menu="map"><b>⌖ Kanto Atlas</b><small>${state.seen.size} zones discovered</small></button><button class="menu-item" data-menu="save"><b>▣ Save</b><small>Keep your progress</small></button></div><p class="notice" id="menuNotice">The next path is always just beyond the tall grass.</p>`;panel.querySelector('[data-close]').onclick=closeOverlay;panel.querySelectorAll('[data-menu]').forEach(b=>b.onclick=()=>menuAction(b.dataset.menu))}
  function menuAction(a){if(a==='map'){closeOverlay();toggleMap();return}if(a==='save'){save();$('#menuNotice').textContent='Journey saved to this device.';return}if(a==='bag'){let used=state.potions>0&&state.party[0].hp<state.party[0].max;if(used){state.potions--;state.party[0].hp=Math.min(state.party[0].max,state.party[0].hp+20);$('#menuNotice').textContent=`Used a Potion. ${state.party[0].name} feels better!`;updateUI()}else $('#menuNotice').textContent=state.potions?'Your team is already at full health.':'Your bag is empty of Potions.';return}$('#menuNotice').textContent=`${state.party.map(m=>`${m.name} Lv.${m.lv} (${m.hp}/${m.max} HP)`).join(' · ')}`}
  function closeOverlay(){for(let s of ['#mapPanel','#menuPanel'])$(s).classList.add('hidden');state.mode='field'}
  function save(){try{localStorage.setItem('yellowJourneySave',JSON.stringify({...state,seen:[...state.seen],seenMons:[...state.seenMons],battle:null,mode:'field'}));toast('Journey saved. See you soon!')}catch(e){toast('Could not save on this device.')}}
  function load(){try{let raw=localStorage.getItem('yellowJourneySave');if(!raw)return;let s=JSON.parse(raw);Object.assign(state,s);state.seen=new Set(s.seen||['0,0']);state.seenMons=new Set(s.seenMons||[]);state.party=s.party||[newMon('Pikachu',5)];state.journal=s.journal||[];state.mode='field';state.battle=null}catch(e){}}
  function start(){load();if(!state.party.length)addMon('Pikachu',5);else if(!state.party[0].name)state.party[0]=newMon('Pikachu',5);visit();if(!state.journal.length){addNote('Pikachu joined you on your first adventure.');addNote('Welcome to Pallet Town, trainer!')}updateUI();}
  window.addEventListener('keydown',e=>{let k=e.key.toLowerCase(),dirs={arrowup:[0,-1],w:[0,-1],arrowdown:[0,1],s:[0,1],arrowleft:[-1,0],a:[-1,0],arrowright:[1,0],d:[1,0]};if(dirs[k]&&state.mode==='field'){e.preventDefault();move(...dirs[k]);return}if(k==='z'||k==='enter'||k===' '){e.preventDefault();if(state.mode==='map'||state.mode==='menu')closeOverlay();else interact()}if(k==='m')toggleMap();if(k==='escape'){if(state.mode==='map'||state.mode==='menu')closeOverlay();else if(state.mode==='field')openMenu()}if(k==='s'&&!e.repeat&&state.mode==='field')save()});
  document.querySelectorAll('[data-dir]').forEach(b=>{let go=()=>{let d=b.dataset.dir;move(d==='left'?-1:d==='right'?1:0,d==='up'?-1:d==='down'?1:0)};b.addEventListener('click',go);b.addEventListener('touchstart',e=>{e.preventDefault();go()},{passive:false})});$('#actionBtn').onclick=interact;$('#menuBtn').onclick=()=>openMenu();$('#openMap').onclick=toggleMap;$('#bagBtn').onclick=()=>{openMenu();menuAction('bag')};$('#saveBtn').onclick=save;$('#editName').onclick=()=>{let n=prompt('What should your trainer be called?',state.trainer);if(n&&n.trim()){state.trainer=n.trim().slice(0,12);updateUI()}};
  start();
})();

