        raw.replace("#MON", "POKéMON")
        .replace("#", "POKé")
        .replace("<PLAYER>", "RED")
        .replace("<RIVAL>", "BLUE")
        .replace("<PKMN>", "PKMN")
        .replace("<TM>", "TM")
        .replace("<TRAINER>", "TRAINER")
        .replace("<PC>", "PC")
        .replace("<ROCKET>", "ROCKET")
        .replace("<USER>", "PIKACHU")
        .replace("<TARGET>", "FOE")
        .replace("@", "")
    )

text_blocks = {}
for pattern in [f"{POKEYELLOW}/text/*.asm", f"{POKEYELLOW}/data/text/*.asm"]:
    for p in glob.glob(pattern):
        with open(p) as f:
            content = strip_debug(f.read())
        cur_labels, cur_paras, cur_lines = [], [], []
        for l in content.splitlines():
            m = re.match(r"^([A-Za-z0-9_]+)::?$", l.strip())
            if m:
                if (cur_paras or cur_lines) and cur_labels:
                    if cur_lines: cur_paras.append(" ".join(cur_lines))
                    txt = "\n\n".join(cur_paras).strip()
                    for lb in cur_labels: text_blocks[lb] = txt
                    cur_labels, cur_paras, cur_lines = [], [], []
                cur_labels.append(m.group(1))
            else:
                tm = re.match(r"^\s*(text|line|next|para|cont)\s+\"([^\"]*)\"", l)
                if tm:
                    kind, raw = tm.groups()
                    s = clean_poke_str(raw)
                    if kind == "para" and cur_lines:
                        cur_paras.append(" ".join(cur_lines))
                        cur_lines = [s]
                    else:
                        cur_lines.append(s)
        if (cur_paras or cur_lines) and cur_labels:
            if cur_lines: cur_paras.append(" ".join(cur_lines))
            txt = "\n\n".join(cur_paras).strip()
            for lb in cur_labels: text_blocks[lb] = txt

# Parse all global label sections across all scripts/*.asm
global_sections = {}
trainer_headers = {}
for p in glob.glob(f"{POKEYELLOW}/scripts/*.asm"):
    with open(p) as f:
        st = strip_debug(f.read())
    # Find trainer headers: Label:\n trainer EVENT, range, BattleLabel, EndLabel, AfterLabel
    for tm in re.finditer(r"([A-Za-z0-9_]+):\s*\n\s*trainer\s+[^,]+,\s*[^,]+,\s*([A-Za-z0-9_]+),\s*([A-Za-z0-9_]+),\s*([A-Za-z0-9_]+)", st):
        th_lbl, b_lbl, e_lbl, a_lbl = tm.groups()
        trainer_headers[th_lbl] = (b_lbl, e_lbl, a_lbl)
    # Split into global label blocks (non-dot labels at start of line)
    lines = st.splitlines()
    cur_lbls = []
    cur_body = []
    for line in lines:
        m = re.match(r"^([A-Za-z0-9_]+)::?$", line.strip())
        if m:
            if cur_body and cur_lbls:
                body_str = "\n".join(cur_body)
                for lb in cur_lbls:
                    global_sections[lb] = body_str
                cur_lbls = []
                cur_body = []
            cur_lbls.append(m.group(1))
        else:
            cur_body.append(line)
    if cur_body and cur_lbls:
        body_str = "\n".join(cur_body)
        for lb in cur_lbls:
            global_sections[lb] = body_str

def resolve_label_text(lbl, depth=0):
    if depth > 4 or not lbl:
        return None
    if "_" + lbl in text_blocks:
        return text_blocks["_" + lbl]
    if lbl in text_blocks:
        return text_blocks[lbl]
    sec = global_sections.get(lbl, "")
    if not sec:
        return None
    # Direct text_far in section
    tfs = re.findall(r"text_far\s+([A-Za-z0-9_]+)", sec)
    out = []
    for tf in tfs:
        if tf in text_blocks and text_blocks[tf] not in out:
            out.append(text_blocks[tf])
    # Follow farcall / call / jp / ld hl
    refs = re.findall(r"(?:farcall|call|jp|ld\s+hl,)\s+([A-Za-z0-9_]+)", sec)
    for r in refs:
        if r in ("PrintText", "TextScriptEnd", "TalkToTrainer", "DisplayTextID", "YesNoChoice", "GiveItem"):
            continue
        sub_txt = resolve_label_text(r, depth + 1)
        if sub_txt and sub_txt not in out:
            out.append(sub_txt)
    if out:
        return "\n\n".join(out[:3])
    return None

print("Trainer headers parsed:", len(trainer_headers), "Global sections:", len(global_sections))
